mapper.select:
SELECT change_log_id, update_version, type, CASE type WHEN 1 THEN '特大版本功能更新' WHEN 2 THEN '功能更新' WHEN 3 THEN 'bug修复' ELSE '未知' END AS type_name, publish_author, public_date, content, link, create_time, update_time FROM t_change_log
AND update_version = #{query.updateVersion}
AND type = #{query.type}
AND INSTR(publish_author, #{query.publishAuthor})
ORDER BY public_date DESC, create_time DESC
